{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-Ie9sWA/src/parser.js","content":"/**
 * Parses the configuration document described in the task's written
 * specification into a tree of nodes. Each node is one of:
 *
 *   { kind: 'table', entries: Map<string, Node>, definedByHeader: boolean }
 *   { kind: 'array-of-tables', items: Node[] }   // items are 'table' nodes
 *   { kind: 'array', items: Node[] }
 *   { kind: 'string'|'integer'|'float'|'boolean', value }
 *
 * `definedByHeader` marks a table that a `[name]` header (not a dotted key,
 * and not an intermediate table on the way to something deeper) most
 * recently made current, so a second such header naming it can be rejected.
 */
import { ConfError } from './errors.js'

const DIGITS = '\\d+(?:_\\d+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS}(?:[eE][+-]?${DIGITS})?|[eE][+-]?${DIGITS})$`)

function isNameChar(ch) {
  return ch !== undefined && /[A-Za-z0-9_-]/.test(ch)
}

function isCommentChar(ch) {
  return ch === '#' || ch === ';'
}

function skipWs(cur) {
  while (cur.i < cur.n && (cur.s[cur.i] === ' ' || cur.s[cur.i] === '\t')) cur.i++
}

function parseBasicString(cur) {
  cur.i++ // opening quote
  let out = ''
  while (true) {
    if (cur.i >= cur.n) throw new ConfError('unterminated string')
    const c = cur.s[cur.i]
    if (c === '"') {
      cur.i++
      return out
    }
    if (c === '\\') {
      cur.i++
      if (cur.i >= cur.n) throw new ConfError('unterminated string')
      const e = cur.s[cur.i]
      if (e === '"') { out += '"'; cur.i++ } else if (e === '\\') { out += '\\'; cur.i++ } else if (e === 'n') { out += '\n'; cur.i++ } else if (e === 't') { out += '\t'; cur.i++ } else if (e === 'r') { out += '\r'; cur.i++ } else if (e === '0') { out += '\0'; cur.i++ } else if (e === 'u') {
        const hex = cur.s.slice(cur.i + 1, cur.i + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          cur.i += 5
        } else {
          throw new ConfError('invalid escape \\u')
        }
      } else {
        throw new ConfError(`invalid escape \\${e}`)
      }
    } else {
      out += c
      cur.i++
    }
  }
}

function parseLiteralString(cur) {
  cur.i++ // opening quote
  const start = cur.i
  while (true) {
    if (cur.i >= cur.n) throw new ConfError('unterminated string')
    if (cur.s[cur.i] === "'") {
      const out = cur.s.slice(start, cur.i)
      cur.i++
      return out
    }
    cur.i++
  }
}

function parseName(cur) {
  skipWs(cur)
  const c = cur.s[cur.i]
  if (c === '"') return parseBasicString(cur)
  if (c === "'") return parseLiteralString(cur)
  const start = cur.i
  while (cur.i < cur.n && isNameChar(cur.s[cur.i])) cur.i++
  if (cur.i === start) throw new ConfError('expected a name')
  return cur.s.slice(start, cur.i)
}

function parseDottedName(cur) {
  const segments = [parseName(cur)]
  while (true) {
    skipWs(cur)
    if (cur.s[cur.i] === '.') {
      cur.i++
      skipWs(cur)
      segments.push(parseName(cur))
    } else break
  }
  return segments
}

function joinPath(base, segments) {
  let p = base
  for (const seg of segments) p = p === '' ? seg : `${p}.${seg}`
  return p
}

function interpretBareword(token) {
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  if (FLOAT_RE.test(token)) return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  throw new ConfError(`invalid value ${token}`)
}

function isBarewordStop(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

function parseValue(cur, path) {
  skipWs(cur)
  const c = cur.s[cur.i]
  if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
    throw new ConfError('expected a value')
  }
  if (c === '[') return parseArray(cur, path)
  if (c === '{') return parseInlineTable(cur, path)
  if (c === '"') return { kind: 'string', value: parseBasicString(cur) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(cur) }
  const start = cur.i
  while (cur.i < cur.n && !isBarewordStop(cur.s[cur.i])) cur.i++
  return interpretBareword(cur.s.slice(start, cur.i))
}

function skipWsAndComment(cur) {
  skipWs(cur)
  if (cur.i < cur.n && isCommentChar(cur.s[cur.i])) cur.i = cur.n
}

function parseArray(cur, path) {
  cur.i++ // '['
  const items = []
  skipWsAndComment(cur)
  if (cur.i >= cur.n) throw new ConfError('unterminated array')
  if (cur.s[cur.i] === ']') {
    cur.i++
    return { kind: 'array', items }
  }
  let idx = 0
  while (true) {
    items.push(parseValue(cur, `${path}[${idx}]`))
    idx++
    skipWsAndComment(cur)
    if (cur.i >= cur.n) throw new ConfError('unterminated array')
    if (cur.s[cur.i] === ']') {
      cur.i++
      break
    }
    if (cur.s[cur.i] === ',') {
      cur.i++
      skipWsAndComment(cur)
      if (cur.i >= cur.n) throw new ConfError('unterminated array')
      if (cur.s[cur.i] === ']') {
        cur.i++
        break
      }
      continue
    }
    throw new ConfError('trailing text after a value')
  }
  return { kind: 'array', items }
}

function assignInto(table, segments, value, basePath) {
  let cur = table
  let path = basePath
  for (let idx = 0; idx < segments.length - 1; idx++) {
    const seg = segments[idx]
    path = path === '' ? seg : `${path}.${seg}`
    const existing = cur.entries.get(seg)
    if (existing === undefined) {
      const t = { kind: 'table', entries: new Map(), definedByHeader: false }
      cur.entries.set(seg, t)
      cur = t
    } else if (existing.kind === 'table') {
      cur = existing
    } else if (existing.kind === 'array-of-tables') {
      cur = existing.items[existing.items.length - 1]
    } else {
      throw new ConfError(`${path} is not a table`)
    }
  }
  const last = segments[segments.length - 1]
  const finalPath = path === '' ? last : `${path}.${last}`
  if (cur.entries.has(last)) throw new ConfError(`key ${finalPath} is defined twice`)
  cur.entries.set(last, value)
}

function parseInlineTable(cur, path) {
  cur.i++ // '{'
  const table = { kind: 'table', entries: new Map(), definedByHeader: false }
  skipWsAndComment(cur)
  if (cur.i >= cur.n) throw new ConfError('unterminated inline table')
  if (cur.s[cur.i] === '}') {
    cur.i++
    return table
  }
  while (true) {
    const segments = parseDottedName(cur)
    skipWs(cur)
    if (cur.s[cur.i] !== '=') throw new ConfError('expected = in an inline table')
    cur.i++
    const valuePath = joinPath(path, segments)
    const value = parseValue(cur, valuePath)
    assignInto(table, segments, value, path)
    skipWsAndComment(cur)
    if (cur.i >= cur.n) throw new ConfError('unterminated inline table')
    if (cur.s[cur.i] === '}') {
      cur.i++
      break
    }
    if (cur.s[cur.i] === ',') {
      cur.i++
      skipWsAndComment(cur)
      if (cur.i >= cur.n) throw new ConfError('unterminated inline table')
      continue
    }
    throw new ConfError('trailing text after a value')
  }
  return table
}

class Document {
  constructor() {
    this.root = { kind: 'table', entries: new Map(), definedByHeader: false }
    this.current = this.root
    this.currentPath = ''
  }

  handleSingleHeader(segments) {
    let cur = this.root
    let path = ''
    for (let idx = 0; idx < segments.length; idx++) {
      const seg = segments[idx]
      path = path === '' ? seg : `${path}.${seg}`
      const isLast = idx === segments.length - 1
      const existing = cur.entries.get(seg)
      if (existing === undefined) {
        const t = { kind: 'table', entries: new Map(), definedByHeader: false }
        cur.entries.set(seg, t)
        cur = t
        if (isLast) cur.definedByHeader = true
      } else if (existing.kind === 'table') {
        if (isLast) {
          if (existing.definedByHeader) throw new ConfError(`table ${path} is defined twice`)
          existing.definedByHeader = true
        }
        cur = existing
      } else if (existing.kind === 'array-of-tables') {
        if (isLast) throw new ConfError(`${path} is not a table`)
        cur = existing.items[existing.items.length - 1]
      } else {
        throw new ConfError(`${path} is not a table`)
      }
    }
    this.current = cur
    this.currentPath = path
  }

  handleArrayHeader(segments) {
    let cur = this.root
    let path = ''
    for (let idx = 0; idx < segments.length - 1; idx++) {
      const seg = segments[idx]
      path = path === '' ? seg : `${path}.${seg}`
      const existing = cur.entries.get(seg)
      if (existing === undefined) {
        const t = { kind: 'table', entries: new Map(), definedByHeader: false }
        cur.entries.set(seg, t)
        cur = t
      } else if (existing.kind === 'table') {
        cur = existing
      } else if (existing.kind === 'array-of-tables') {
        cur = existing.items[existing.items.length - 1]
      } else {
        throw new ConfError(`${path} is not a table`)
      }
    }
    const last = segments[segments.length - 1]
    const finalPath = path === '' ? last : `${path}.${last}`
    let arr = cur.entries.get(last)
    if (arr === undefined) {
      arr = { kind: 'array-of-tables', items: [] }
      cur.entries.set(last, arr)
    } else if (arr.kind !== 'array-of-tables') {
      throw new ConfError(`${finalPath} is not an array of tables`)
    }
    const t = { kind: 'table', entries: new Map(), definedByHeader: false }
    arr.items.push(t)
    this.current = t
    this.currentPath = finalPath
  }
}

function handleHeaderLine(cur, doc) {
  cur.i++ // consume '['
  let isArray = false
  if (cur.s[cur.i] === '[') {
    isArray = true
    cur.i++
  }
  const segments = parseDottedName(cur)
  skipWs(cur)
  if (cur.s[cur.i] !== ']') throw new ConfError('unterminated table header')
  cur.i++
  if (isArray) {
    skipWs(cur)
    if (cur.s[cur.i] !== ']') throw new ConfError('unterminated table header')
    cur.i++
  }
  skipWs(cur)
  if (cur.i < cur.n && !isCommentChar(cur.s[cur.i])) throw new ConfError('trailing text after a table header')
  if (isArray) doc.handleArrayHeader(segments)
  else doc.handleSingleHeader(segments)
}

function handleAssignmentLine(cur, doc) {
  const segments = parseDottedName(cur)
  skipWs(cur)
  if (cur.s[cur.i] !== '=') throw new ConfError('expected key = value')
  cur.i++
  const valuePath = joinPath(doc.currentPath, segments)
  const value = parseValue(cur, valuePath)
  skipWs(cur)
  if (cur.i < cur.n && !isCommentChar(cur.s[cur.i])) throw new ConfError('trailing text after a value')
  assignInto(doc.current, segments, value, doc.currentPath)
}

function parseLine(raw, doc) {
  const cur = { s: raw, i: 0, n: raw.length }
  let j = 0
  while (j < cur.n && (raw[j] === ' ' || raw[j] === '\t')) j++
  if (j >= cur.n) return // blank line
  const c = raw[j]
  if (c === '#' || c === ';') return // whole-line comment
  cur.i = j
  if (c === '[') handleHeaderLine(cur, doc)
  else handleAssignmentLine(cur, doc)
